'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var copy = require( '@stdlib/utils/copy' );
var DEFAULTS = require( './defaults.json' );


// VARIABLES //

/**
* Matches a single-line return annotation.
*
* Regular expression: `/^\/\/(\s*)(?:(e\.g\.,)\s*)?(returns|=>)(\s*)/`
*
* -   `^`
*     -   match the beginning of the string
*
* -   `\/\/`
*     -   match a `//` literal
*
* -   `(\s*)`
*     -   capture zero or more whitespace characters (the spacing before the keyword)
*
* -   `(?:(e\.g\.,)\s*)?`
*     -   optionally match the literal `e.g.,` followed by zero or more whitespace characters, capturing `e.g.,`
*
* -   `(returns|=>)`
*     -   capture the annotation keyword `returns` or `=>`
*
* -   `(\s*)`
*     -   capture zero or more whitespace characters (the spacing after the keyword)
*
* @constant
* @type {RegExp}
* @default /^\/\/(\s*)(?:(e\.g\.,)\s*)?(returns|=>)(\s*)/
*/
var RE_ANNOTATION = /^\/\/(\s*)(?:(e\.g\.,)\s*)?(returns|=>)(\s*)/;
var rule;


// FUNCTIONS //

/**
* Rule for validating that return annotations have correct spacing.
*
* @param {Object} context - ESLint context
* @returns {Object} validators
*/
function main( context ) {
	var options;
	var source;
	var opts;

	opts = copy( DEFAULTS );
	options = context.options[ 0 ];
	if ( options ) {
		if ( hasOwnProp( options, 'numSpaces' ) ) {
			opts.numSpaces = options.numSpaces;
		}
	}
	source = context.getSourceCode();

	/**
	* Reports the error message.
	*
	* @private
	* @param {Object} loc - error location info
	* @param {string} msg - error message
	*/
	function report( loc, msg ) {
		context.report({
			'node': null,
			'message': msg,
			'loc': loc
		});
	}

	/**
	* Checks whether return annotations in the current program have correct spacing.
	*
	* @private
	* @param {ASTNode} node - node to examine
	*/
	function validate( node ) {
		var comments;
		var i;

		comments = source.getAllComments( node );
		for ( i = 0; i < comments.length; i++ ) {
			checkComment( comments[ i ] );
		}
	}

	/**
	* Checks whether a comment is a return annotation and, if so, whether it has correct spacing.
	*
	* @private
	* @param {Object} comment - comment to examine
	*/
	function checkComment( comment ) {
		var spacingBefore;
		var spacingAfter;
		var expected;
		var matches;
		var keyword;
		var prefix;
		var text;
		var msg;

		// Only check single-line comments:
		if ( comment.type !== 'Line' ) {
			return;
		}
		// Reconstruct the comment text with the leading slashes:
		text = '//' + comment.value;

		matches = text.match( RE_ANNOTATION );
		if ( matches ) {
			spacingBefore = matches[ 1 ].length;
			prefix = matches[ 2 ] || '';  // 'e.g.,' or empty
			keyword = matches[ 3 ];       // 'returns' or '=>'
			spacingAfter = matches[ 4 ].length;

			// Check spacing before keyword (must be exactly 1 space):
			if ( spacingBefore !== 1 ) {
				if ( prefix ) {
					msg = 'Return annotation `' + prefix + ' ' + keyword + '` should have exactly 1 space after `//`. Found ' + spacingBefore + ' space(s).';
				} else {
					msg = 'Return annotation `' + keyword + '` should have exactly 1 space after `//`. Found ' + spacingBefore + ' space(s).';
				}
				report( comment.loc, msg );
			}
			// Check spacing after keyword (configurable):
			expected = opts.numSpaces;
			if ( spacingAfter !== expected ) {
				msg = 'Return annotation keyword `' + keyword + '` should be followed by ' + expected + ' space(s). Found ' + spacingAfter + ' space(s).';
				report( comment.loc, msg );
			}
		}
	}

	return {
		'Program': validate
	};
}


// MAIN //

rule = {
	'meta': {
		'docs': {
			'description': 'enforce spacing after return annotations in single-line comments'
		},
		'schema': [
			{
				'type': 'object',
				'properties': {
					'numSpaces': {
						'type': 'integer',
						'minimum': 1
					}
				},
				'additionalProperties': false
			}
		]
	},
	'create': main
};


// EXPORTS //

module.exports = rule;
